"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[16664],{24147:e=>{e.exports=JSON.parse('{"functions":[{"name":"Init","desc":"Scans `workspace.SpawnVolumes` and rebuilds the internal weighted cache from\\nall `BasePart` children, reading each part\'s optional `SpawnGroup` attribute.\\nMust be called at least once before `GetRandomPoint`. Safe to call again if\\nspawn volumes change at runtime \u2014 any disabled groups remain disabled.","params":[],"returns":[],"function_type":"method","source":{"line":91,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}},{"name":"GetRandomPoint","desc":"Returns a uniformly random `Vector3` point inside one of the *enabled* spawn\\nvolumes. Volume selection is weighted by world-space volume so larger parts\\nare proportionally more likely to be chosen. Volumes in disabled groups are\\nexcluded.\\n\\nReturns `nil` if `Init` has not been called or no enabled volumes remain\\n(e.g. every group is disabled).","params":[],"returns":[{"desc":"A random world-space position, or `nil`.","lua_type":"Vector3?"}],"function_type":"static","source":{"line":122,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}},{"name":"GetGroups","desc":"Returns the distinct `SpawnGroup` values authored across the spawn volumes.\\nUseful for validation/debug.","params":[],"returns":[{"desc":"distinct authored group names.","lua_type":"{ string }"}],"function_type":"method","source":{"line":158,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}},{"name":"IsGroupEnabled","desc":"Returns `true` unless `groupName` is currently disabled. Unknown or ungrouped\\nnames read `true` (they are never disabled).","params":[{"name":"groupName","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"}],"function_type":"method","source":{"line":181,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}},{"name":"SetGroupEnabled","desc":"Enables or disables spawning from every volume whose `SpawnGroup` attribute\\nequals `groupName`. Idempotent; rebuilds the active weighted set. Ungrouped\\nvolumes are unaffected. `warn`s if no authored volume carries `groupName`\\n(typo guard) but still records the state so it applies if that group is\\nauthored later.","params":[{"name":"groupName","desc":"","lua_type":"string"},{"name":"enabled","desc":"","lua_type":"boolean"}],"returns":[],"function_type":"method","source":{"line":196,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}}],"properties":[],"types":[],"name":"SpawnHelper","desc":"Utility for volume-weighted random spawn point selection, with runtime\\ntoggling of named spawn-volume groups.\\n\\nOn startup the module locates (or creates) a `Folder` named\\n`SpawnVolumes` in `workspace`.  Each `BasePart` child of that folder is\\ntreated as a spawn volume; its weight is proportional to its world-space\\nvolume (`Size.X * Size.Y * Size.Z`).\\n\\nA `BasePart` may carry an optional **`SpawnGroup`** string attribute. Parts\\nsharing a value form a togglable group; `SetGroupEnabled` disables/enables\\nspawning from all volumes in a group at runtime (used by the pirate-ship\\nevent to keep junk out of the ship\'s path). Parts with no `SpawnGroup`\\nattribute are *ungrouped* \u2014 always active and never affected by toggles.\\n\\n`Init` must be called before `GetRandomPoint` to populate the internal\\nweighted cache.\\n\\n```lua\\nlocal SpawnHelper = require(path.to.SpawnHelper)\\n\\nSpawnHelper:Init()\\nSpawnHelper:SetGroupEnabled(\\"Left\\", false) -- pause spawns in the \\"Left\\" group\\nlocal point = SpawnHelper.GetRandomPoint()\\nif point then\\n\\tcharacter:PivotTo(CFrame.new(point))\\nend\\n```","source":{"line":36,"path":"src/ReplicatedStorage/SharedModules/SpawnHelper.luau"}}')}}]);